function dedupeEvents(events) {
  const seen = new Map();
  for (const e of events) {
    const key = `${e.type}:${e.entityId}`;
    const prev = seen.get(key);
    if (!prev || e.timestamp > prev.timestamp) {
      seen.set(key, e);
    }
  }
  return [...seen.values()].sort((a, b) => a.timestamp - b.timestamp);
}
